package com.ansh.bank.card.service;
import java.util.*; import com.ansh.bank.common.config.SeedData; import com.ansh.bank.card.dto.CardDtos.*; import org.springframework.stereotype.Service;
/** Manage visible card block state. */ @Service public class CardService {private final SeedData d; public CardService(SeedData d){this.d=d;} /** List cards. */ public List<Response> all(){return d.cards.stream().map(this::map).toList();} /** Change a card's state. */ public Response set(String id,String status){for(int i=0;i<d.cards.size();i++){var c=d.cards.get(i);if(c.id().equals(id)){var n=new SeedData.Card(c.id(),c.name(),c.last4(),status);d.cards.set(i,n);return map(n);}}throw new IllegalArgumentException("Card not found");} private Response map(SeedData.Card c){return new Response(c.id(),c.name(),c.last4(),c.status());} }
